// 1. 阻塞 IO
char buf[1024];
int n = recv(sockfd, buf, sizeof(buf), 0); // 阻塞直到数据到达
// 线程在这里一直等待

// 2. 非阻塞 IO
#include <fcntl.h>
#include <errno.h>

// 设置非阻塞
int flags = fcntl(sockfd, F_GETFL, 0);
fcntl(sockfd, F_SETFL, flags | O_NONBLOCK);

while (1) {
    int n = recv(sockfd, buf, sizeof(buf), 0);
    if (n > 0) {
        // 数据就绪
        break;
    } else if (n < 0 && errno == EAGAIN) {
        // 数据未就绪，继续轮询
        continue;
    }
}

// 3. IO 多路复用（select）
fd_set readfds;
FD_ZERO(&readfds);
FD_SET(sockfd, &readfds);

int ready = select(sockfd + 1, &readfds, NULL, NULL, NULL);
if (ready > 0 && FD_ISSET(sockfd, &readfds)) {
    int n = recv(sockfd, buf, sizeof(buf), 0);
}

// 4. 异步 IO（Linux aio）
#include <aio.h>

struct aiocb cb;
cb.aio_fildes = sockfd;
cb.aio_buf = buf;
cb.aio_nbytes = sizeof(buf);
cb.aio_sigevent.sigev_notify = SIGEV_THREAD;
cb.aio_sigevent.sigev_notify_function = completion_handler;

aio_read(&cb); // 立即返回
// completion_handler 在数据就绪并拷贝完成后被调用
